import type { Result } from '../shared/research.ts';
import type { ResearchTask } from './research.ts';
export function escapeHtml(text: string) { return text.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('"', '&quot;').replaceAll("'", '&#39;'); }
export function safeLink(value: string) { return /^https?:\/\//i.test(value) ? escapeHtml(value) : '#'; }
function cell(value: string) { const safe = /^[=+@-]/.test(value) ? `'${value}` : value; return `"${safe.replaceAll('"', '""')}"`; }
export function csvReport(task: ResearchTask, results: Result[]) {
  return '\uFEFF' + ['账号,平台,粉丝数,地区,本地判断,标签,链接,逐条件核验,证据映射,入选,画像标注,基础事实,互动率及样本,照片资源', ...results.map(result => [result.creator.handle, result.creator.platform, String(result.creator.followers), result.creator.region ?? '', result.verdict, result.tags.join(' / '), result.creator.profileUrl, JSON.stringify(result.judgments), JSON.stringify(result.creator.evidence.map(evidence => ({ ...evidence, ...(evidence.assetId ? { screenshotUrl: `/api/assets/${evidence.assetId}` } : {}) }))), String(result.selected ?? false), JSON.stringify(result.annotations ?? []), JSON.stringify(result.creator.facts ?? {}), JSON.stringify(result.creator.engagement ?? {}), JSON.stringify(result.creator.photoUrls ?? [])].map(cell).join(','))].join('\r\n');
}
export function evidenceReport(result: Result, image?: (id: string) => string) {
  return `<details open><summary>完整证据映射与截图</summary>${result.creator.evidence.map(evidence => {
    let screenshot = '';
    if (evidence.assetId) { try { const data = image?.(evidence.assetId); if (data?.startsWith('data:image/png;base64,')) screenshot = `<img style="max-width:100%" alt="截图证据 ${escapeHtml(evidence.id)}" src="${data}">`; } catch { screenshot = '<p>截图暂不可读取，请在工作室核对该证据编号。</p>'; } }
    return `<section><h4>${escapeHtml(evidence.id)} · ${escapeHtml(evidence.kind)}</h4><a href="${safeLink(evidence.url)}">原始来源</a><p>提供方：${escapeHtml(evidence.provider)} · 捕获：${new Date(evidence.capturedAt).toISOString()} · 发布时间：${escapeHtml(evidence.publishedAt ?? '日期未知')}${evidence.assetId ? ` · 截图编号：${escapeHtml(evidence.assetId)}` : ''}</p><pre style="white-space:pre-wrap">${escapeHtml(evidence.text)}</pre>${screenshot}</section>`;
  }).join('')}</details>`;
}
export function htmlReport(task: ResearchTask, results: Result[], image?: (id: string) => string) {
  const verdict = { match: '符合要求', no_match: '不符合', unknown: '待核实' };
  return `<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>${escapeHtml(task.title)}</title><style>body{font:15px/1.9 sans-serif;max-width:960px;margin:48px auto;padding:0 24px;color:#233c37;background:#f5f3ed}article{border-top:1px solid #bfcabb;padding:24px 0}a{color:#285d48}small{color:#69786b}table{border-collapse:collapse;width:100%}td,th{text-align:left;border-bottom:1px solid #dedfd6;padding:10px;vertical-align:top}</style><h1>${escapeHtml(task.title)}</h1><p>目标 ${task.requested} 人；本地已合格 ${task.matched} 人；已核验 ${task.evaluated} 人。</p><p>${escapeHtml(task.detail)}</p><small>来源：WaveSurge + 本地核验。远端搜索完成不代表本地条件通过。本次报告包含 ${results.length} 条筛选记录。报告更新时间：${new Date(task.updatedAt).toISOString()}</small>${results.map(result => `<article><h2><a href="${safeLink(result.creator.profileUrl)}">${escapeHtml(result.creator.displayName)}</a> · ${verdict[result.verdict]}${result.selected === true ? ' · 已入选' : result.selected === false && result.verdict === 'match' ? ' · 合格备选' : ''}</h2><p>${escapeHtml(result.creator.platform)} / ${escapeHtml(result.creator.handle)} / 粉丝 ${escapeHtml(String(result.creator.followers ?? result.creator.facts?.followers?.rawValue ?? '未知'))} / ${escapeHtml(result.creator.region ?? '未知')}</p>${result.creator.engagement ? `<p>近期互动率：${result.creator.engagement.rate === null ? '未知' : `${(result.creator.engagement.rate * 100).toFixed(2)}%`}；样本 ${result.creator.engagement.sampleSize} 条；算法 ${escapeHtml(result.creator.engagement.formula)}</p>` : ''}<p>标签：${result.tags.map(escapeHtml).join('、')}</p>${(result.annotations ?? []).map(item => `<p>画像 ${escapeHtml(item.dimensionId)}：${item.status === 'supported' ? item.values.map(escapeHtml).join('、') : '待核实'}；${escapeHtml(item.reason)}；证据 ${item.evidenceIds.map(escapeHtml).join('、')}</p>`).join('')}<table><tr><th>条件</th><th>判断</th><th>依据</th></tr>${result.judgments.map(item => `<tr><td>${escapeHtml(item.label ?? item.criterionId)}</td><td>${verdict[item.verdict]}</td><td>${escapeHtml(item.reason)}<br>${item.evidenceIds.map(id => { const evidence = result.creator.evidence.find(source => source.id === id)!; return `<a href="${safeLink(evidence.url)}">${escapeHtml(evidence.kind)} ${escapeHtml(evidence.publishedAt ?? '日期未知')}</a>`; }).join('<br>')}</td></tr>`).join('')}</table>${evidenceReport(result, image)}</article>`).join('')}</html>`;
}

campaignApi:
import type { FastifyInstance } from 'fastify';
import type { CampaignService } from './campaign.ts';
import type { Campaign } from '../shared/campaign.ts';
import { escapeHtml, safeLink, evidenceReport } from './reports.ts';
export function registerCampaigns(app: FastifyInstance, service: CampaignService, image?: (id: string) => string) {
  app.get('/api/campaigns', async () => service.facts());
  app.get<{ Params: { id: string } }>('/api/campaigns/:id', async (request, reply) => { const campaign = service.store.get<Campaign>('campaign', request.params.id); if (!campaign) return reply.code(404).send({ error: 'Campaign 不存在' }); return service.summary(campaign); });
  app.post<{ Params: { id: string }; Body: { revision: number } }>('/api/campaigns/:id/start', { schema: { body: { type: 'object', required: ['revision'], additionalProperties: false, properties: { revision: { type: 'integer', minimum: 1 } } } } }, async (request, reply) => { try { return service.start(request.params.id, request.body.revision); } catch (error) { return reply.code(409).send({ error: (error as Error).message }); } });
  app.get<{ Params: { id: string } }>('/api/campaigns/:id/report', async (request, reply) => {
    const campaign = service.store.get<Campaign>('campaign', request.params.id); if (!campaign) return reply.code(404).send({ error: 'Campaign 不存在' }); const summary = service.summary(campaign);
    reply.header('Content-Security-Policy', "default-src 'none'; style-src 'unsafe-inline'; img-src data:"); return reply.type('text/html; charset=utf-8').send(`<!doctype html><html lang="zh"><meta charset="utf-8"><title>${escapeHtml(campaign.title)}</title><style>body{max-width:960px;margin:48px auto;font:16px/1.8 sans-serif;padding:24px;color:#172f2d}article{border-bottom:1px solid #ddd;padding:24px 0}a{color:#116653}</style><h1>${escapeHtml(campaign.title)}</h1><p>${escapeHtml(campaign.goal)}</p><p>受众：${escapeHtml(campaign.audience)}</p><p>方案 v${campaign.revision} · ${summary.status} · 去重入选 ${summary.matched}/${summary.requested}，合格账号池 ${summary.qualifyingUnique}。同一平台账号只占一个类型配额；跨平台同一人缺乏可靠关联时不猜测合并。</p>${summary.groups.map(group => `<article><h2>${escapeHtml(group.spec.title)} · ${group.matched}/${group.spec.count}</h2><p>${escapeHtml(group.rationale)}</p><pre>${escapeHtml(JSON.stringify(group.spec, null, 2))}</pre>${summary.selections.filter(selection => selection.groupId === group.id).map(selection => { const result = summary.results.find(item => item.id === selection.resultId)!; return `<p><a href="${safeLink(result.creator.profileUrl)}">${escapeHtml(result.creator.displayName)} @${escapeHtml(result.creator.handle)}</a></p>${evidenceReport(result, image)}`; }).join('')}${group.taskId ? `<a href="/api/reports/${encodeURIComponent(group.taskId)}">逐条件证据与未入选结果</a>` : ''}</article>`).join('')}</html>`);
  });
}

workDelivery:
import type { Store } from './store.ts';
import type { Task } from '../shared/contracts.ts';
import type { Result } from '../shared/research.ts';
import type { ResearchTask } from './research.ts';
import { deliverReport } from './delivery.ts';
export type WorkItem = { kind: 'research' | 'enrichment' | 'campaign'; id: string; title: string; reportUrl: string };
export type WorkBatch = { id: string; items: WorkItem[]; sealed: boolean; delivered?: boolean };
const terminal = (status: string | undefined) => ['completed', 'partial', 'failed', 'cancelled'].includes(status ?? '');
export function registerWork(store: Store, callId: string, item: WorkItem) {
 const owner = store.get<{ requestId: string }>('tool-owner', callId); const id = owner?.requestId ?? callId;
 store.transaction(() => {
  const batch = store.get<WorkBatch>('work-batch', id) ?? { id, items: [], sealed: !owner };
  if (!batch.items.some(work => work.id === item.id)) batch.items.push(item);
  store.set('work-batch', id, batch);
  const kind = item.kind === 'campaign' ? 'campaign' : 'task'; const task = store.get<Task>(kind, item.id)!;
  store.set(kind, item.id, { ...task, deliveryBatchId: id });
 });
}
export function workSummary(store: Store, batch: WorkBatch) {
 const states = batch.items.map(item => item.kind === 'campaign' ? store.get<Task>('campaign-state', item.id) : store.task<Task>(item.id));
 return { states, ready: batch.sealed && states.every(state => state && terminal(state.status)) };
}
export function deliverWorkBatches(store: Store, now: number) {
 for (const batch of store.list<WorkBatch>('work-batch')) {
  if (batch.delivered) continue; const { states, ready } = workSummary(store, batch); if (!ready) continue;
  store.transaction(() => {
   deliverReport(store, `request-${batch.id}`, batch.items.map(item => item.id), `本次请求的 ${batch.items.length} 项工作已全部结束。\n\n${batch.items.map((item, i) => `- ${item.title}：${states[i]!.status === 'completed' ? '已完成' : states[i]!.status === 'partial' ? '已结束，仍有缺额或失败' : states[i]!.status === 'cancelled' ? '已取消' : '未完成'}；${states[i]!.detail} [查看报告](${item.reportUrl})`).join('\n')}\n\n[查看本次综合报告](/api/work-batches/${encodeURIComponent(batch.id)}/report) · [下载综合 CSV](/api/work-batches/${encodeURIComponent(batch.id)}/report?format=csv)`, now);
   batch.delivered = true; store.set('work-batch', batch.id, batch);
  });
 }
}
export function sealWork(store: Store, inputIds: string[], now: number) {
 store.transaction(() => { for (const id of inputIds) { const batch = store.get<WorkBatch>('work-batch', id); if (batch) { batch.sealed = true; store.set('work-batch', id, batch); } } deliverWorkBatches(store, now); });
}
export function workResults(store: Store, batch: WorkBatch) {
 const sourceIds = new Set<string>(); const restricted = new Set<string>(); const campaignSources = new Set<string>(); const selectedCampaignResults = new Set<string>();
 for (const item of batch.items) {
  if (item.kind === 'research') sourceIds.add(item.id);
  else if (item.kind === 'campaign') { for (const id of store.get<{ childTaskIds: string[] }>('campaign', item.id)!.childTaskIds) { sourceIds.add(id); campaignSources.add(id); } for (const selection of store.get<{ selections: { resultId: string }[] }>('campaign-state', item.id)?.selections ?? []) selectedCampaignResults.add(selection.resultId); }
  else for (const id of store.get<{ resultIds: string[] }>('enrichment', item.id)!.resultIds) restricted.add(id);
 }
 const results = store.list<Result>('result').filter(result => sourceIds.has(result.taskId) || restricted.has(result.id)).map(result => {
  const source = store.task<ResearchTask>(result.taskId)!;
  return { ...result, ...(campaignSources.has(result.taskId) ? { selected: selectedCampaignResults.has(result.id) } : {}), judgments: result.judgments.map(judgment => ({ ...judgment, label: judgment.label ?? source.spec.criteria.find(c => c.id === judgment.criterionId)?.label ?? judgment.criterionId })) };
 });
 const { states } = workSummary(store, batch);
 const task = { id: batch.id, title: '本次请求综合报告', requested: states.reduce((sum, s) => sum + (s?.requested ?? 0), 0), evaluated: states.reduce((sum, s) => sum + (s?.evaluated ?? 0), 0), matched: states.reduce((sum, s) => sum + (s?.matched ?? 0), 0), updatedAt: Math.max(0, ...states.map(s => s?.updatedAt ?? 0)), detail: batch.items.map((item, i) => `${item.title}：${states[i]?.detail ?? '尚未执行'}`).join('\n') } as ResearchTask;
 return { task, results };
}
